-- Asistencia, puntualidad, reincidencias y novedades para nomina.
create table if not exists public.hr_attendance_imports(
 id uuid primary key default gen_random_uuid(),source text not null default 'MANUAL' check(source in('MANUAL','BIOMETRICO','ARCHIVO')),device_reference text not null default '',file_name text not null default '',records_count integer not null default 0,imported_by uuid not null references public.app_users(id),created_at timestamptz not null default now()
);
create table if not exists public.hr_attendance_records(
 id uuid primary key default gen_random_uuid(),employee_id uuid not null references public.hr_employees(id),work_date date not null,scheduled_entry time not null default '08:00',scheduled_exit time not null default '16:00',entry_at timestamptz,exit_at timestamptz,
 status text not null default 'PRESENTE' check(status in('PRESENTE','TARDANZA','AUSENCIA_JUSTIFICADA','AUSENCIA_NO_JUSTIFICADA','LICENCIA','VACACIONES','FERIADO')),late_minutes integer not null default 0 check(late_minutes>=0),worked_minutes integer not null default 0 check(worked_minutes>=0),justification text not null default '',document_url text not null default '',source text not null default 'MANUAL' check(source in('MANUAL','BIOMETRICO','ARCHIVO')),import_id uuid references public.hr_attendance_imports(id),
 created_by uuid not null references public.app_users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(employee_id,work_date)
);
create table if not exists public.hr_attendance_payroll_novelties(
 id uuid primary key default gen_random_uuid(),employee_id uuid not null references public.hr_employees(id),attendance_record_id uuid not null unique references public.hr_attendance_records(id),payroll_year integer not null,payroll_month integer not null check(payroll_month between 1 and 12),novelty_type text not null check(novelty_type in('AUSENCIA_NO_JUSTIFICADA','TARDANZA')),minutes integer not null default 0,amount numeric(18,2) not null default 0 check(amount>=0),status text not null default 'PENDIENTE' check(status in('PENDIENTE','APROBADA','APLICADA','ANULADA')),approved_by uuid references public.app_users(id),approved_at timestamptz,created_at timestamptz not null default now(),applied_at timestamptz
);
create index if not exists hr_attendance_employee_date_idx on public.hr_attendance_records(employee_id,work_date desc);create index if not exists hr_attendance_novelty_period_idx on public.hr_attendance_payroll_novelties(payroll_year,payroll_month,status);
alter table public.hr_attendance_imports enable row level security;alter table public.hr_attendance_records enable row level security;alter table public.hr_attendance_payroll_novelties enable row level security;
revoke all on public.hr_attendance_imports,public.hr_attendance_records,public.hr_attendance_payroll_novelties from anon,authenticated;

create or replace function public.hr_apply_payroll_adjustments() returns trigger language plpgsql security definer set search_path=public as $$declare v_permission numeric;v_attendance numeric;v_amount numeric;begin
 select coalesce(sum(a.amount),0) into v_permission from public.hr_payroll_adjustments a join public.hr_payroll_batches b on b.payroll_year=a.payroll_year and b.payroll_month=a.payroll_month where a.employee_id=new.employee_id and b.id=new.batch_id and a.status<>'ANULADO';
 select coalesce(sum(a.amount),0) into v_attendance from public.hr_attendance_payroll_novelties a join public.hr_payroll_batches b on b.payroll_year=a.payroll_year and b.payroll_month=a.payroll_month where a.employee_id=new.employee_id and b.id=new.batch_id and a.status='APROBADA';
 v_amount:=least(v_permission+v_attendance,new.net_amount);if v_amount>0 then update public.hr_payroll_batch_lines set other_deductions=other_deductions+v_amount,total_deductions=total_deductions+v_amount,net_amount=greatest(net_amount-v_amount,0) where id=new.id;update public.hr_payroll_adjustments a set status='APLICADO',applied_at=now() from public.hr_payroll_batches b where b.id=new.batch_id and a.employee_id=new.employee_id and a.payroll_year=b.payroll_year and a.payroll_month=b.payroll_month and a.status='PENDIENTE';update public.hr_attendance_payroll_novelties a set status='APLICADA',applied_at=now() from public.hr_payroll_batches b where b.id=new.batch_id and a.employee_id=new.employee_id and a.payroll_year=b.payroll_year and a.payroll_month=b.payroll_month and a.status='APROBADA';end if;return new;end $$;

create or replace function public.list_hr_attendance(p_token text,p_year integer,p_month integer)
returns jsonb language plpgsql security definer set search_path=public,extensions as $$declare v_user public.app_users;v_start date:=make_date(p_year,p_month,1);v_end date:=(make_date(p_year,p_month,1)+interval '1 month - 1 day')::date;begin v_user:=public.hr_authenticated_user(p_token);if v_user.id is null or (v_user.role<>'Administrador' and not coalesce((v_user.permissions->>'ver_recursos_humanos')::boolean,false)) then return jsonb_build_object('success',false,'error','No posee permiso para consultar asistencia.');end if;
 return jsonb_build_object('success',true,
 'employees',coalesce((select jsonb_agg(jsonb_build_object('id',e.id,'employee_code',e.employee_code,'full_name',e.full_name,'position_name',e.position_name,'direction_name',e.direction_name,'department_name',e.department_name) order by e.full_name) from public.hr_employees e where e.employment_status<>'Desvinculado' and (v_user.role='Administrador' or public.hr_employee_in_user_scope(v_user,e))),'[]'::jsonb),
 'records',coalesce((select jsonb_agg(to_jsonb(x) order by x.work_date desc,x.full_name) from(select a.*,e.employee_code,e.full_name,e.position_name,e.direction_name,e.department_name,n.id novelty_id,n.amount novelty_amount,n.status novelty_status from public.hr_attendance_records a join public.hr_employees e on e.id=a.employee_id left join public.hr_attendance_payroll_novelties n on n.attendance_record_id=a.id where a.work_date between v_start and v_end and (v_user.role='Administrador' or public.hr_employee_in_user_scope(v_user,e)))x),'[]'::jsonb),
 'summary',coalesce((select jsonb_agg(to_jsonb(x) order by x.unjustified_absences desc,x.late_count desc,x.full_name) from(select e.id employee_id,e.employee_code,e.full_name,e.position_name,e.direction_name,e.department_name,count(a.id) work_records,count(*) filter(where a.status='PRESENTE') present_count,count(*) filter(where a.status='TARDANZA') late_count,coalesce(sum(a.late_minutes),0) late_minutes,count(*) filter(where a.status='AUSENCIA_JUSTIFICADA') justified_absences,count(*) filter(where a.status='AUSENCIA_NO_JUSTIFICADA') unjustified_absences,round(coalesce(sum(a.worked_minutes),0)/60.0,2) worked_hours,case when count(*) filter(where a.status='AUSENCIA_NO_JUSTIFICADA')>=2 then 'CRITICA' when count(*) filter(where a.status='TARDANZA')>=3 then 'ALTA' when count(*) filter(where a.status='TARDANZA')>=2 then 'MEDIA' else 'NORMAL' end alert_level from public.hr_employees e left join public.hr_attendance_records a on a.employee_id=e.id and a.work_date between v_start and v_end where e.employment_status<>'Desvinculado' and (v_user.role='Administrador' or public.hr_employee_in_user_scope(v_user,e)) group by e.id)x),'[]'::jsonb),
 'indicators',(select jsonb_build_object('records',count(*),'present',count(*) filter(where status='PRESENTE'),'late',count(*) filter(where status='TARDANZA'),'justified',count(*) filter(where status='AUSENCIA_JUSTIFICADA'),'unjustified',count(*) filter(where status='AUSENCIA_NO_JUSTIFICADA'),'late_minutes',coalesce(sum(late_minutes),0)) from public.hr_attendance_records where work_date between v_start and v_end));end $$;

create or replace function public.manage_hr_attendance(p_token text,p_action text,p_data jsonb)
returns jsonb language plpgsql security definer set search_path=public,extensions as $$declare v_user public.app_users;v_record public.hr_attendance_records;v_employee public.hr_employees;v_id uuid;v_status text;v_entry timestamptz;v_exit timestamptz;v_late integer;v_worked integer;v_amount numeric;begin v_user:=public.hr_authenticated_user(p_token);if v_user.id is null or (v_user.role<>'Administrador' and not coalesce((v_user.permissions->>'editar_recursos_humanos')::boolean,false)) then return jsonb_build_object('success',false,'error','No posee permiso para gestionar asistencia.');end if;
 if p_action='REGISTRAR' then select * into v_employee from public.hr_employees where id=(p_data->>'employee_id')::uuid and employment_status<>'Desvinculado';if v_employee.id is null then return jsonb_build_object('success',false,'error','Empleado no válido.');end if;v_status:=upper(p_data->>'status');v_entry:=nullif(p_data->>'entry_at','')::timestamptz;v_exit:=nullif(p_data->>'exit_at','')::timestamptz;v_late:=case when v_entry is not null then greatest(0,extract(epoch from (v_entry-((p_data->>'work_date')::date+coalesce(nullif(p_data->>'scheduled_entry','')::time,'08:00'::time))))/60)::integer else 0 end;v_worked:=case when v_entry is not null and v_exit is not null then greatest(0,extract(epoch from(v_exit-v_entry))/60)::integer else 0 end;if v_status='PRESENTE' and v_late>0 then v_status:='TARDANZA';end if;
  insert into public.hr_attendance_records(employee_id,work_date,scheduled_entry,scheduled_exit,entry_at,exit_at,status,late_minutes,worked_minutes,justification,document_url,source,created_by) values(v_employee.id,(p_data->>'work_date')::date,coalesce(nullif(p_data->>'scheduled_entry','')::time,'08:00'),coalesce(nullif(p_data->>'scheduled_exit','')::time,'16:00'),v_entry,v_exit,v_status,v_late,v_worked,trim(coalesce(p_data->>'justification','')),trim(coalesce(p_data->>'document_url','')),coalesce(nullif(p_data->>'source',''),'MANUAL'),v_user.id) on conflict(employee_id,work_date) do update set scheduled_entry=excluded.scheduled_entry,scheduled_exit=excluded.scheduled_exit,entry_at=excluded.entry_at,exit_at=excluded.exit_at,status=excluded.status,late_minutes=excluded.late_minutes,worked_minutes=excluded.worked_minutes,justification=excluded.justification,document_url=excluded.document_url,source=excluded.source,updated_at=now() returning id into v_id;
 elsif p_action='GENERAR_NOVEDAD' then select a.* into v_record from public.hr_attendance_records a where a.id=(p_data->>'record_id')::uuid for update;if v_record.id is null or v_record.status not in('TARDANZA','AUSENCIA_NO_JUSTIFICADA') then return jsonb_build_object('success',false,'error','Solo las tardanzas y ausencias no justificadas generan novedades.');end if;select * into v_employee from public.hr_employees where id=v_record.employee_id;v_amount:=case when v_record.status='AUSENCIA_NO_JUSTIFICADA' then round(v_employee.monthly_salary/23.83,2) else round((v_employee.monthly_salary/23.83/8/60)*v_record.late_minutes,2) end;insert into public.hr_attendance_payroll_novelties(employee_id,attendance_record_id,payroll_year,payroll_month,novelty_type,minutes,amount) values(v_record.employee_id,v_record.id,extract(year from v_record.work_date)::integer,extract(month from v_record.work_date)::integer,v_record.status,v_record.late_minutes,v_amount) on conflict(attendance_record_id) do update set minutes=excluded.minutes,amount=excluded.amount,status='PENDIENTE' returning id into v_id;
 elsif p_action='APROBAR_NOVEDAD' then if v_user.role<>'Administrador' and not coalesce((v_user.permissions->>'aprobar_recursos_humanos')::boolean,false) then return jsonb_build_object('success',false,'error','No posee permiso para aprobar novedades de nómina.');end if;update public.hr_attendance_payroll_novelties set status='APROBADA',approved_by=v_user.id,approved_at=now() where id=(p_data->>'novelty_id')::uuid and status='PENDIENTE' returning id into v_id;
 else return jsonb_build_object('success',false,'error','Acción de asistencia inválida.');end if;insert into public.security_audit_log(actor_user_id,action,module,detail) values(v_user.id,'ASISTENCIA_'||p_action,'Recursos Humanos',p_data||jsonb_build_object('result_id',v_id));return jsonb_build_object('success',true,'id',v_id);end $$;
grant execute on function public.list_hr_attendance(text,integer,integer),public.manage_hr_attendance(text,text,jsonb) to anon,authenticated;
